$pdo=db();$id=(int)($_GET['id']??0);$product=$pdo&&commerce_schema_ready($pdo)?commerce_product($pdo,$id):null;if(!$product){http_response_code(404);$pageTitle='Product unavailable | Moleqra';}
if($product)$pageTitle=$product['name'].' | Moleqra';
require __DIR__.'/includes/header.php';
